package kr.pdfmemorynotes;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
final class Store extends SQLiteOpenHelper {
 Store(Context c){super(c,"pdfmemory.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE docs(id INTEGER PRIMARY KEY,name TEXT,path TEXT UNIQUE,pages INTEGER,done INTEGER DEFAULT 0,last INTEGER DEFAULT 0,status TEXT DEFAULT '',error TEXT DEFAULT '')");d.execSQL("CREATE TABLE pages(doc INTEGER,page INTEGER,lines TEXT,PRIMARY KEY(doc,page))");d.execSQL("CREATE TABLE cards(id TEXT PRIMARY KEY,doc INTEGER,number TEXT,q TEXT,a TEXT,qp TEXT,ap TEXT,uncertain INTEGER,edited INTEGER DEFAULT 0,due INTEGER DEFAULT 0)");}public void onUpgrade(SQLiteDatabase d,int o,int n){}
 long doc(String name,String path,int pages){SQLiteDatabase d=getWritableDatabase();try(Cursor c=d.rawQuery("SELECT id FROM docs WHERE path=?",new String[]{path})){if(c.moveToFirst())return c.getLong(0);}ContentValues v=new ContentValues();v.put("name",name);v.put("path",path);v.put("pages",pages);return d.insertOrThrow("docs",null,v);}
 List<JSONObject> rows(String sql,String...args){List<JSONObject> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery(sql,args)){while(c.moveToNext()){JSONObject o=new JSONObject();try{for(int i=0;i<c.getColumnCount();i++)o.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getString(i));}catch(JSONException e){throw new IllegalStateException(e);}out.add(o);}}return out;}
 JSONObject get(long id){List<JSONObject> l=rows("SELECT * FROM docs WHERE id=?",""+id);return l.isEmpty()?null:l.get(0);}
 void state(long id,String status,String error){ContentValues v=new ContentValues();v.put("status",status);v.put("error",error);getWritableDatabase().update("docs",v,"id=?",new String[]{""+id});}
 void last(long id,int page){ContentValues v=new ContentValues();v.put("last",page);getWritableDatabase().update("docs",v,"id=?",new String[]{""+id});}
 void page(long doc,int page,List<Splitter.Line> lines)throws Exception{JSONArray a=new JSONArray();for(Splitter.Line l:lines)a.put(new JSONArray().put(l.left).put(l.top).put(l.right).put(l.bottom).put(l.text).put(l.blue).put(l.inferred));SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{ContentValues v=new ContentValues();v.put("doc",doc);v.put("page",page);v.put("lines",a.toString());d.insertWithOnConflict("pages",null,v,SQLiteDatabase.CONFLICT_REPLACE);v=new ContentValues();v.put("done",page+1);d.update("docs",v,"id=?",new String[]{""+doc});d.setTransactionSuccessful();}finally{d.endTransaction();}}
 List<Splitter.Line> lines(long doc,int page){List<Splitter.Line> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT lines FROM pages WHERE doc=? AND page=?",new String[]{""+doc,""+page})){if(c.moveToFirst()){JSONArray a=new JSONArray(c.getString(0));for(int i=0;i<a.length();i++){JSONArray l=a.getJSONArray(i);Splitter.Line line=new Splitter.Line(page,(float)l.getDouble(0),(float)l.getDouble(1),(float)l.getDouble(2),(float)l.getDouble(3),l.getString(4),l.optBoolean(5));line.inferred=l.optBoolean(6);out.add(line);}}}catch(Exception e){throw new IllegalStateException(e);}return out;}
 void rebuild(long doc,int count){Splitter.scan(page->lines(doc,page),count,c->cards(doc,java.util.Collections.singletonList(c)));}
 static String parts(List<Splitter.Part> ps){JSONArray a=new JSONArray();for(Splitter.Part p:ps)try{a.put(new JSONArray().put(p.page).put(p.top).put(p.bottom));}catch(JSONException e){throw new IllegalArgumentException(e);}return a.toString();}
 void cards(long doc,List<Splitter.Card> cards){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{for(Splitter.Card c:cards){String id=doc+":"+c.key;ContentValues v=new ContentValues();v.put("id",id);v.put("doc",doc);v.put("number",c.number);v.put("q",c.question);v.put("a",c.answer);v.put("qp",parts(c.questionParts));v.put("ap",parts(c.answerParts));v.put("uncertain",c.uncertain?1:0);if(d.update("cards",v,"id=? AND edited=0",new String[]{id})==0)d.insertWithOnConflict("cards",null,v,SQLiteDatabase.CONFLICT_IGNORE);}d.setTransactionSuccessful();}finally{d.endTransaction();}}
 void edit(String id,String q,String a){ContentValues v=new ContentValues();v.put("q",q);v.put("a",a);v.put("edited",1);v.put("uncertain",0);getWritableDatabase().update("cards",v,"id=?",new String[]{id});}
 void rate(String id,int days){ContentValues v=new ContentValues();v.put("due",System.currentTimeMillis()+days*86400000L);getWritableDatabase().update("cards",v,"id=?",new String[]{id});}
}
